import{_ as a,o as i,c as e,a1 as t}from"./chunks/framework.DIevSSiF.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function l(o,s,d,h,r,p){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Requirements: Git, Bash, Python 3.10+, and one supported native coding host. No Node, no npm, no package manager — the stable release clone <em>is</em> the install.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadow-v1.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --depth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://github.com/firstbitelabsllc/shadow.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shadow</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shadow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>The namespaced tag is immutable. To update, read GitHub Latest, fetch tags, check out its exact <code>shadow-v*</code> tag, and rerun <code>bash install.sh</code>. Clone <code>main</code> only when you deliberately want moving development source.</p><p><code>install.sh</code> links <code>bin/shadow</code> into <code>~/.local/bin</code> and mounts the skill in every host root that already exists (<code>~/.claude/skills</code>, <code>~/.agents/skills</code>, <code>~/.cursor/skills</code>). Two flags change that:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # put the command somewhere else</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-skills</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # command only, skip the host mounts</span></span></code></pre></div><p>The mount points at the same repository; it does not copy state or credentials. The default install also writes Shadow&#39;s marker-delimited standing block into Claude and Codex host instructions without replacing surrounding text. Cold Cursor directive activation is unsupported because Cursor exposes no equivalent reviewed writable file. The installer does not invent a path or ask you to paste into an unverified setting; Cursor&#39;s skill mount and sealed host runner remain supported. <code>--no-skills</code> deliberately skips both mounts and host-instruction installation.</p><h2 id="upgrading-from-the-old-name" tabindex="-1">Upgrading from the old name <a class="header-anchor" href="#upgrading-from-the-old-name" aria-label="Permalink to &quot;Upgrading from the old name&quot;">​</a></h2><p>Shadow shipped under a different name before 0.1.0. Its compatibility path is gone: evidence lives in <code>.shadow/</code>, and a repository still carrying the pre-rename evidence directory shows as dirty until that directory is renamed to <code>.shadow/</code> or deleted. Remove the old global install and its mounts, then re-run <code>bash install.sh</code> so <code>~/.claude/skills</code>, <code>~/.agents/skills</code>, and <code>~/.cursor/skills</code> point at this checkout.</p>`,9)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
